css:
.card {
  width: 230px;
  height: 230px;
  position: relative;
  background-color: rgb(255, 255, 255);
  border-bottom: 3px solid #4c6bff;
  overflow: hidden;
  -webkit-box-shadow: 0px 12px 65px -39px rgba(0, 0, 0, 1);
  -moz-box-shadow: 0px 12px 65px -39px rgba(0, 0, 0, 1);
  box-shadow: 0px 12px 65px -39px rgba(0, 0, 0, 1);
  border-radius: 5px;
}
.BG {
  width: 100%;
  height: 100%;
  position: relative;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
}
.BG svg {
  position: absolute;
  width: 50%;
  left: -20%;
  top: -20%;
  fill: rgb(244, 244, 244);
  transition: all 0.5s;
}
.content {
  width: 100%;
  height: 100%;
  position: absolute;
  top: 0;
  left: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-start;
  padding: 25px;
  color: rgb(30, 30, 30);
  gap: 3px;
}
.heading {
  font-size: 1.4em;
  font-weight: 700;
  color: rgb(30, 30, 30);
}
.sub-heading {
  margin-top: -7px;
  font-size: 0.9em;
  font-weight: 600;
  color: rgb(30, 30, 30);
}
.sub-sub-heading {
  font-size: 0.7em;
  color: rgb(128, 128, 128);
}

.email {
  width: 100%;
  height: 25px;
  margin-top: 20px;
  border: none;
  border-bottom: 1px solid #c0c7ec;
  outline: none;
  font-size: 0.7em;
  background-color: transparent;
}
.card-btn {
  margin-top: 20px;
  height: 30px;
  width: 100%;
  border: none;
  background: linear-gradient(60deg, #4c6bff, #8196ff);
  color: white;
  border-radius: 30px;
  cursor: pointer;
}

.card:hover .BG svg {
  left: 0%;
  top: 0%;
  transform: rotate(180deg) scale(9);
  fill: #c0c7ec;
}
